SELECT a.SEC_SNAME AS `股票名称`, a.SEC_CODE AS `股票代码`, f.ENDDATE AS `报表截止日`, ROUND(f.F110101 / 10000, 1) AS `归母净利润(万)` FROM GET_A_SEC_CODE a INNER JOIN VIEW_STK_FIN_IDX f ON a.COMCODE = f.COMCODE AND f.ENDDATE = '2025-12-31 00:00:00' AND f.F110101 IS NOT NULL AND f.ISVALID = 1 WHERE a.SEC_SNAME LIKE '%中国平安%' AND a.ISVALID = 1 ORDER BY f.ENDDATE DESC LIMIT 1;
